js4m1.solucao:
const preco = Number(prompt("Preço do jogo: "));
const porSemana = Number(prompt("Guardado por semana: "));

let total = 0;
let semana = 0;
while (total < preco) {
  total += porSemana;
  semana++;
  console.log(`Semana ${semana}: R$ ${total}`);
}
console.log(`Meta atingida na semana ${semana}!`);

