js4m3.solucao:
const mensagem = prompt("Mensagem: ");

let secreta = "";
let vogais = 0;
for (const letra of mensagem) {
  if ("aeiou".includes(letra)) {
    secreta += "*";
    vogais++;
  } else {
    secreta += letra;
  }
}
console.log(secreta);
console.log(`Vogais escondidas: ${vogais}`);

