js4m4.solucao:
let rodadas = 0;
let total = 0;

while (true) {
  const entrada = prompt("Pontos da rodada: ");
  if (entrada === "fim") {
    break;
  }
  const pontos = Number(entrada);
  if (pontos < 0) {
    console.log(`Valor inválido: ${pontos}`);
    continue;
  }
  total += pontos;
  rodadas++;
}

console.log(`Rodadas válidas: ${rodadas}`);
console.log(`Total: ${total}`);

