js4m5.solucao:
const largura = Number(prompt("Largura: "));
const altura = Number(prompt("Altura: "));

for (let linha = 1; linha <= altura; linha++) {
  let desenho = "";
  for (let coluna = 1; coluna <= largura; coluna++) {
    const parede = linha === 1 || linha === altura || coluna === 1 || coluna === largura;
    if (parede) {
      desenho += "#";
    } else {
      desenho += ".";
    }
  }
  console.log(desenho);
}

