js4m6.solucao:
const secreto = Math.floor(Math.random() * 100) + 1;
let tentativas = 0;
let acertou = false;

while (tentativas < 7) {
  const palpite = Number(prompt("Seu palpite: "));
  if (palpite < 1 || palpite > 100) {
    console.log("Digite um número de 1 a 100.");
    continue;
  }
  tentativas++;
  if (palpite === secreto) {
    acertou = true;
    break;
  }
  if (secreto > palpite) {
    console.log("Mais alto!");
  } else {
    console.log("Mais baixo!");
  }
}

if (acertou) {
  if (tentativas === 1) {
    console.log("Acertou de primeira!");
  } else {
    console.log(`Acertou em ${tentativas} tentativas!`);
  }
} else {
  console.log(`Fim de jogo! O número era ${secreto}.`);
}
